import { apiJson } from "./client";
import { type MetricCandidate } from "./evidence";

/**
 * Conversational intake: building a profile by asking rather than by parsing a file.
 *
 * The questions are derived deterministically from what the profile is missing, not
 * generated by a model, which is what makes the interview terminate, stay on topic, and
 * resume after the tab is closed. Answers are stored as the user typed them.
 */

/** What the interview is for, given how much the profile already holds. */
export type IntakeMode = "empty" | "skeleton" | "stale" | "complete";

export type IntakeQuestion = {
  id: string;
  stage: string;
  /** Where this answer belongs in the profile. Comes from the server, never invented. */
  target_path: string;
  /** `target_path` in the user's words. Show this; `target_path` is internal. */
  label: string;
  question: string;
  /** Why we are asking, in the user's terms. */
  rationale: string;
  input_kind: "text" | "long_text" | "list";
  examples: string[];
  /**
   * Clickable sentence shapes for the achievement questions, with `___` where the figure
   * goes. Same type as the evidence panel's because it is the same affordance for the
   * same question; empty for the questions whose answer is not a figure, which fall back
   * to `examples`.
   */
  metrics: MetricCandidate[];
  required: boolean;
};

/**
 * A question already answered, carried so the user can read it back and revise it.
 *
 * Kept out of `questions` on the server: putting answered questions back into the
 * pending list would stop the interview from terminating and the stage counts from
 * reaching done. But omitting them entirely is what made the panel write-once.
 */
export type IntakeAnswered = {
  question_id: string;
  target_path: string;
  question: string;
  /** The profile location in the user's words, e.g. 「某某科技 · 后端专家 · 负责范围」. */
  label: string;
  answer: string;
};

export type IntakeStage = {
  id: string;
  label: string;
  remaining: number;
  done: boolean;
};

export type IntakePlan = {
  mode: IntakeMode;
  role_family: string;
  role_label: string;
  questions: IntakeQuestion[];
  /** Already answered, oldest first. */
  answered: IntakeAnswered[];
  stages: IntakeStage[];
  answered_count: number;
  can_generate: boolean;
  /** What is still missing before a draft can be generated, phrased for the user. */
  blocking: string[];
  version: number;
};

export type IntakeAnswerInput = {
  question_id: string;
  target_path: string;
  question: string;
  answer: string;
};

/** One write that landed on the profile, in terms the user can check. */
export type IntakeAppliedWrite = {
  path: string;
  label: string;
  value: string;
};

export type IntakeAnswerResult = {
  profile_id: string;
  version: number;
  stored: number;
  /** Dotted paths. Kept for API parity; the UI reads `applied` for labels and values. */
  applied_paths: string[];
  /** Structured fields these answers filled, so a write to the profile is never silent. */
  applied: IntakeAppliedWrite[];
  plan: IntakePlan;
};

/** One candidate bullet from a dictated answer, with the slot it would occupy. */
export type IntakeSplitSegment = {
  /** The plan's id for the slot this segment fills. Never derived on the client. */
  question_id: string;
  text: string;
  /** Resolved server-side: the free slot this segment lands in. */
  target_path: string;
  /** `target_path` in the user's words. */
  label: string;
};

export type IntakeSplitResult = {
  question_id: string;
  segments: IntakeSplitSegment[];
  /** True when the answer held more than one point, i.e. worth showing the split. */
  split: boolean;
};

export function getIntakePlan(
  profileId: string,
  options?: { limit?: number },
): Promise<IntakePlan> {
  const query = options?.limit ? `?limit=${options.limit}` : "";
  return apiJson<IntakePlan>(`/profiles/${profileId}/intake${query}`);
}

export function submitIntakeAnswers(
  profileId: string,
  answers: IntakeAnswerInput[],
): Promise<IntakeAnswerResult> {
  return apiJson<IntakeAnswerResult>(`/profiles/${profileId}/intake-answers`, {
    method: "POST",
    body: JSON.stringify({ answers }),
  });
}

/**
 * Break one dictated answer into the points it contains. Read-only: nothing is stored
 * by asking, so the user confirms or edits the segments before they are submitted as
 * ordinary answers.
 *
 * The split is punctuation-based on the server and no model sees the text, which is why
 * it can be offered automatically — it cannot reword or drop what the user wrote.
 */
export function splitIntakeAnswer(
  profileId: string,
  input: { question_id: string; target_path: string; answer: string },
): Promise<IntakeSplitResult> {
  return apiJson<IntakeSplitResult>(`/profiles/${profileId}/intake-split`, {
    method: "POST",
    body: JSON.stringify(input),
  });
}

/** Headline for each mode: says what this interview will do, before it starts. */
